using System;using System.Linq;using System.Text.RegularExpressions;using NUnit.Framework;using UnityEngine;using Janseon.Core.Battle.Contracts;using Janseon.Data.Authoring;using Janseon.Data.Fingerprints;using Janseon.Data.Validation;
namespace Janseon.Foundation.Tests { public sealed class Area1ContentFingerprintTests { static GameDataCatalogAsset C(){var c=ScriptableObject.CreateInstance<GameDataCatalogAsset>();c.contentSchema=1;c.contentVersion="area1-static-content-v1";c.fingerprintVersion="content-fingerprint-v1";c.cards=new[]{"a","b","c","d","e","f"}.Select((id,n)=>{var x=ScriptableObject.CreateInstance<CardDefinitionAsset>();x.stableId="card."+id;x.coreCardId=id;x.kind=n<4?CardKind.Character:CardKind.Stronghold;x.rechargeTicks=new[]{300,600,450,600,900,750}[n];x.effect=new[]{-3,10,1,1,5,1}[n];x.effectKey=new[]{"front_damage","morale","front_damage","cardinal_reposition","front_heal","retreat"}[n];return x;}).ToArray();c.unitRoles=new[]{"guard","assault","archer"}.Select((id,n)=>{var x=ScriptableObject.CreateInstance<UnitRoleDefinitionAsset>();x.stableId="unit.role."+id;x.coreRole=new[]{"근위","돌격","궁수"}[n];x.maxHp=new[]{30,20,14}[n];x.power=new[]{4,6,3}[n];x.rangeMin=1;x.rangeMax=new[]{1,1,3}[n];x.moveTicksPerCell=10;x.attackCooldownTicks=30;return x;}).ToArray();c.formations=new[]{ScriptableObject.CreateInstance<FormationDefinitionAsset>()};c.formations[0].stableId="formation.default-3x3";c.formations[0].rowCount=3;c.formations[0].columnCount=3;c.formations[0].slots=new FormationSlotDefinition[6];for(int i=0;i<6;i++)c.formations[0].slots[i]=new FormationSlotDefinition{roleStableId=c.unitRoles[i/2].stableId,row=i/2,column=i%2-1,facing=Janseon.Core.CardinalDirection.East};c.stations=new[]{"a","b","c"}.Select(id=>{var x=ScriptableObject.CreateInstance<StationDefinitionAsset>();x.stableId="station."+id;x.coreStationId=id; x.neighbors=new string[0];return x;}).ToArray();return c;}static string F(GameDataCatalogAsset c)=>CanonicalContentFingerprint.Compute(GameDataCatalogIndexBuilder.Project(c));[Test]public void ReorderedSourceArrays_ProduceSameFingerprint(){var a=C();var b=C();b.cards=b.cards.Reverse().ToArray();b.unitRoles=b.unitRoles.Reverse().ToArray();Assert.AreEqual(F(a),F(b));}[Test]public void GameplayFieldChange_ChangesFingerprint(){var a=C();var b=C();b.cards[0].rechargeTicks=301;Assert.AreNotEqual(F(a),F(b));}[Test]public void StableIdChange_ChangesFingerprint(){var a=C();var b=C();b.cards[0].stableId="card.changed";Assert.AreNotEqual(F(a),F(b));}[Test]public void OrdinalOrdering_IsCultureIndependent(){var x=new[]{"card.a.b","card.a-b"};var y=x.OrderBy(z=>z,StringComparer.Ordinal).ToArray();Assert.AreEqual("card.a-b",y[0]);}[Test]public void Fingerprint_IsLowercaseSha256(){Assert.IsTrue(Regex.IsMatch(F(C()),"^[0-9a-f]{64}$"));}[Test]public void PresentationReferenceChange_DoesNotChangeFingerprint(){var a=C();var b=C();b.cards[0].name="different inspector name";Assert.AreEqual(F(a),F(b));}}}
